import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/services.dart';
import 'package:shared_preferences/shared_preferences.dart';

/// One file per value in assets/sfx (generated by tool/gen_sfx.py).
enum Sfx { tap, correct, wrong, coin, powerup, levelUp, crash, jump, drop, perfect, merge, swipe, win, lose, tick }

/// Fire-and-forget sound effects. Silent until [init] runs (so tests stay silent).
abstract final class Sound {
  static const _key = 'sound_muted';
  static SharedPreferences? _prefs;
  static final _players = <Sfx, AudioPlayer>{};
  static bool muted = false;

  static void init(SharedPreferences prefs) {
    _prefs = prefs;
    muted = prefs.getBool(_key) ?? false;
  }

  static void setMuted(bool value) {
    muted = value;
    _prefs?.setBool(_key, value);
  }

  static void play(Sfx s, {double volume = 1}) {
    if (_prefs == null || muted) return;
    final p = _players[s] ??= AudioPlayer()..setReleaseMode(ReleaseMode.stop);
    // Audio must never break gameplay: ignore every playback error.
    p.play(AssetSource('sfx/${s.name}.wav'), volume: volume, mode: PlayerMode.lowLatency).catchError((_) {});
  }

  /// Sound and haptic on the same frame, for taps on physical-looking controls.
  static void tap() {
    play(Sfx.tap, volume: 0.6);
    HapticFeedback.lightImpact();
  }
}
